// components/AudioPlayerWrapper.js
import React from 'react';
import AudioPlayer from './AudioPlayer';
import { useAudio } from '@/context/AudioContext';

const AudioPlayerWrapper = () => {
  const { audioDetails, stopChapter } = useAudio();

  if (!audioDetails) return null;

  return (
    <AudioPlayer
      audioUrl={audioDetails.audioUrl}
      chapterTitle={audioDetails.chapterTitle}
      book={audioDetails.book}
      onClose={stopChapter}
    />
  );
};

export default AudioPlayerWrapper;
